-- Trading days: 17:00 New York the day before to 16:59:59 New York on TRADE_DATE,
-- both stored in GMT. GMT_OFFSET is the MT4 server offset (GMT+2 under EST,
-- GMT+3 under EDT), so the New York close is midnight server time.
-- Every calendar day: weekends and holidays get a row too, for weekend
-- adjustments and statements. Monday still opens Sunday 17:00, Sunday covers
-- Saturday 17:00 to Sunday 16:59:59. A Sunday with a clock change is 23 or 25 hours.
DROP TABLE IF EXISTS reference.eod_time;

CREATE TABLE reference.eod_time (
    TRADE_DATE  DATE     NOT NULL PRIMARY KEY,
    OPEN_TIME   DATETIME NOT NULL COMMENT '17:00:00 New York the day before, GMT',
    CLOSE_TIME  DATETIME NOT NULL COMMENT '16:59:59 New York on TRADE_DATE, GMT',
    GMT_OFFSET  TINYINT  NOT NULL COMMENT 'MT4 server offset: 2 under EST, 3 under EDT'
);

